/* From Uiverse.io by Shoh2008 - Tags: checkbox */
.__UIV_SCOPE__ .checkbox-wrapper-37 input[type="checkbox"] {
  display: none;
}

.__UIV_SCOPE__ .checkbox-wrapper-37 .terms-label {
  cursor: pointer;
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .checkbox-wrapper-37 .terms-label .label-text {
  margin-left: 10px;
}

.__UIV_SCOPE__ .checkbox-wrapper-37 .checkbox-svg {
  width: 30px;
  height: 30px;
}

.__UIV_SCOPE__ .checkbox-wrapper-37 .checkbox-box {
  fill: #fff;
  stroke: #ff7a00;
  stroke-dasharray: 800;
  stroke-dashoffset: 800;
  transition: stroke-dashoffset 0.6s ease-in;
}

.__UIV_SCOPE__ .checkbox-wrapper-37 .checkbox-tick {
  stroke: #ff7a00;
  stroke-dasharray: 172;
  stroke-dashoffset: 172;
  transition: stroke-dashoffset 0.6s ease-in;
}

.__UIV_SCOPE__ .checkbox-wrapper-37 input[type="checkbox"]:checked + .terms-label .checkbox-box,
  .__UIV_SCOPE__ .checkbox-wrapper-37 input[type="checkbox"]:checked + .terms-label .checkbox-tick {
  stroke-dashoffset: 0;
}
